import{_ as a,o,c as t,a2 as r}from"./chunks/framework.w09axK8o.js";const p=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":null}'),n={name:"guide/index.md"};function d(i,e,s,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p>VersePC2 提供了一套轻量的插件机制，允许第三方开发者向启动器扩展能力。插件以 <strong>zip 包</strong> 形式分发，内含一份 <code>plugin.json</code> 清单；用户在<strong>插件市场</strong>中浏览、下载并安装。</p><h2 id="插件是什么" tabindex="-1">插件是什么 <a class="header-anchor" href="#插件是什么" aria-label="Permalink to &quot;插件是什么&quot;">​</a></h2><p>一个插件就是一个符合约定的目录（最终会解压到 <code>data/plugins/&lt;id&gt;/</code>），核心是一份 <code>plugin.json</code>。安装、列表、卸载都由启动器统一管理，你无需关心数据落盘细节。</p><h2 id="你能做什么" tabindex="-1">你能做什么 <a class="header-anchor" href="#你能做什么" aria-label="Permalink to &quot;你能做什么&quot;">​</a></h2><ul><li><strong>功能插件</strong>（<code>category: function</code>）— 新增独立页面或向现有页面插入卡片，例如开服（<code>verse-server-host</code>）。</li><li><strong>个性化插件</strong>（<code>category: personalize</code>）— 用 Vue 模板并配合 <code>main</code> 脚本对<strong>整个启动器前端</strong>做自定义：主题、外观、桌面宠物挂件等。</li><li><strong>开服插件</strong>（<code>category: server</code>）— 在功能列表中展示的本地开服能力。</li></ul><h2 id="插件市场" tabindex="-1">插件市场 <a class="header-anchor" href="#插件市场" aria-label="Permalink to &quot;插件市场&quot;">​</a></h2><p>启动器的插件市场读取一个远程索引 <code>index.json</code>（默认仓库为 <code>doujie081231/verseplugin</code>）。只要你的插件包能下载、索引能解析，它就会出现在市场里。</p><h2 id="开始" tabindex="-1">开始 <a class="header-anchor" href="#开始" aria-label="Permalink to &quot;开始&quot;">​</a></h2><p>下一节带你从零搭建一个最小插件。</p>',10)])])}const g=a(n,[["render",d]]);export{p as __pageData,g as default};
